mapper.select:
SELECT ROW_NUMBER() OVER ( ORDER BY
dv_name dv_addr dv_reg_date dv_name
ASC DESC
) AS rn , dv_id, dv_name, dv_addr, dv_addr_detail, dv_serial_number, dv_status, dv_reg_date FROM tbl_device WHERE 1=1
AND dv_reg_date >= STR_TO_DATE(#{startDate},'%Y-%m-%d') AND dv_reg_date < DATE_ADD(STR_TO_DATE(#{endDate},'%Y-%m-%d'),INTERVAL 1 DAY)
AND ( dv_name LIKE CONCAT( '%', REPLACE(#{searchKeyword}, '_', '\\_'), '%' ) ESCAPE '\\' OR dv_addr LIKE CONCAT( '%', REPLACE(#{searchKeyword}, '_', '\\_'), '%' ) ESCAPE '\\' )
LIMIT #{recordCountPerPage}
OFFSET #{firstIndex}

SELECT dv_ip
FROM tbl_device
WHERE dv_id = #{dvId}

mapper.insert:
INSERT INTO tbl_device(
	dv_org_id
	, dv_name
	, dv_addr
	, dv_addr_detail
	, dv_ip
	, dv_status
	, dv_reg_user
	, dv_mod_user
	, dv_reg_date
	, dv_mod_date
	, dv_serial_number
	, dv_lat
	, dv_lng
)
VALUES(
	1
	, #{dvName}
	, #{dvAddr}
	, #{dvAddrDetail}
	, #{dvIp}
	, #{dvStatus}
	, 1
	, 1
	, NOW()
	, NOW()
	, #{dvSerialNumber}
	, #{dvLat}
	, #{dvLng}
)

mapper.update:
UPDATE tbl_device
SET
	dv_name = #{dvName}
	, dv_addr = #{dvAddr}
	, dv_addr_detail = #{dvAddrDetail}
	, dv_ip = #{dvIp}
	, dv_status = #{dvStatus}
	, dv_mod_user = 1
	, dv_mod_date = NOW()
	, dv_serial_number = #{dvSerialNumber}
	, dv_lat = #{dvLat}
	, dv_lng = #{dvLng}
WHERE dv_id = #{dvId}

